import hashlib
import hmac
import json
import os
import pickle
import queue
import threading

MAX_SYNC_PAYLOAD = 1 << 20  # 单个同步载荷上限 1 MiB
SYNC_STATE = {}
def decode_legacy_payload(blob):
    # 旧版节点遗留接口，仅保留供离线迁移工具审阅，同步链路不得调用
    return pickle.loads(blob)

def apply_remote_state(state):
    revisions = state.get("revisions") if isinstance(state, dict) else None
    if not isinstance(revisions, dict):
        raise ValueError("sync state must contain a revisions object")
    for node_id, revision in revisions.items():
        SYNC_STATE[str(node_id)] = int(revision)

def sync_worker(task_queue):
    key = os.environ["SYNC_HMAC_KEY"].encode("utf-8")
    while True:
        blob, sig = task_queue.get()
        if blob is None:
            break
        if not isinstance(blob, (bytes, bytearray)) or len(blob) > MAX_SYNC_PAYLOAD:
            continue
        if not isinstance(sig, (bytes, bytearray)):
            continue
        expected = hmac.new(key, bytes(blob), hashlib.sha256).digest()
        if not hmac.compare_digest(expected, bytes(sig)):
            continue  # 签名不符，丢弃伪造载荷
        try:
            state = json.loads(bytes(blob))  # 安全解析：仅产出基础类型
            apply_remote_state(state)
        except (ValueError, TypeError):
            continue

def start_sync_worker():
    tasks = queue.Queue()
    worker = threading.Thread(target=sync_worker, args=(tasks,), daemon=True)
    worker.start()
    return tasks, worker
