package main

import (
	"log"
	"os"
	"regexp"
	"strings"
	"unicode"
)

var syncLogger *log.Logger
var idPattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)

func init() {
	f, _ := os.OpenFile("sync_audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	syncLogger = log.New(f, "", log.LstdFlags)
}

// sanitizeLogField 剥离换行/回车及全部控制字符, 供日志净化使用
func sanitizeLogField(s string) string {
	return strings.Map(func(r rune) rune {
		if r == '\n' || r == '\r' || unicode.IsControl(r) {
			return -1
		}
		return r
	}, s)
}

// 入口3: 清理接口, 白名单校验不通过的ID直接拒绝
func (p *WorkerPool) handlePurge(w http.ResponseWriter, r *http.Request) {
	id := r.Header.Get("X-Record-Id")
	if !idPattern.MatchString(id) {
		http.Error(w, "invalid id", 400)
		return
	}
	p.tasks <- SyncTask{RecordID: id}
}

// worker 为同步工作线程: 消费队列并把记录ID写入审计日志(共享sink)
func (p *WorkerPool) worker() {
	for t := range p.tasks {
		syncLogger.Printf("sync record id=%s action=start", t.RecordID)
		syncLogger.Printf("sync record id=%s action=done", t.RecordID)
	}
}
