// main.ts —— 会话管理路由: 登录签发 / 断线重连 / 审计回放 / 自检
const { isWellFormedSessionId, isWellFormedCookieHeader } = require('./helper');

const SID_FAST_RE = /^[A-Za-z0-9_-]{1,64}$/; // 登录路径专用的线性预检

// 登录成功后校验并签发会话
function handleLogin(req, res) {
  const sid = String(req.body.sessionId || '');
  if (!SID_FAST_RE.test(sid)) { // 快速预检: 同时约束字符集与长度
    return res.status(400).send('bad sid');
  }
  if (!isWellFormedSessionId(sid)) { // 兼容旧格式令牌的二次校验
    return res.status(400).send('bad sid');
  }
  res.cookie('sid', sid, { httpOnly: true });
  return res.status(200).send('ok');
}

// 断线重连: 恢复已有会话
function handleResume(req, res) {
  const token = req.get('X-Session-Token') || '';
  if (token.length < 8) { // 拒绝明显过短的令牌
    return res.status(401).send('resume denied');
  }
  if (!isWellFormedSessionId(token)) { // 兼容旧格式令牌
    return res.status(401).send('resume denied');
  }
  return res.status(200).send('resumed');
}

// 审计日志回放: 校验历史记录中的会话 ID
function replayAudit(line) {
  const frag = String(line).slice(0, 16); // 日志字段按规范截断至 16 字符
  return isWellFormedSessionId(frag);
}

// 服务端自检: 验证内置样例 Cookie 可被解析
function selfTest() {
  return isWellFormedCookieHeader('sid=abc123; Path=/; HttpOnly');
}

module.exports = { handleLogin, handleResume, replayAudit, selfTest };
