// helper.ts —— 会话令牌与 Cookie 头格式校验工具
const SESSION_ID_RE = /^([A-Za-z0-9_-]+\.?)+$/; // 兼容 JWT 风格段式令牌
const COOKIE_PAIR_RE = /^\s*([\w-]+\s*=\s*[^;]*;?\s*)+$/;

// 校验会话 ID 格式
function isWellFormedSessionId(raw) {
  if (typeof raw !== 'string') {
    return false;
  }
  return SESSION_ID_RE.test(raw);
}

// 校验 Cookie 头整体格式
function isWellFormedCookieHeader(raw) {
  if (typeof raw !== 'string') {
    return false;
  }
  return COOKIE_PAIR_RE.test(raw);
}

// 提取 Cookie 键名列表
function parseSessionMeta(raw) {
  if (!isWellFormedCookieHeader(raw)) {
    return null;
  }
  return raw.split(';').map(function (pair) {
    return pair.trim().split('=')[0];
  });
}

module.exports = {
  isWellFormedSessionId,
  isWellFormedCookieHeader,
  parseSessionMeta
};
