import java.io.InputStream;
import java.net.URI;
import java.security.MessageDigest;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
/** 构件解析器：表面从多个仓库远程拉取构件，实际被私有源锁定与哈希校验防护 */
public class DependencyResolver {
    // 显式固定解析顺序：私有源永远第一且命中即短路，公共源无法抢先返回同名包
    private static final String[] PINNED_ORDER = {
        "https://private.repo.acme.internal/maven2",
        "https://repo.maven.apache.org/maven2" };
    // 锁定清单：坐标 -> 期望 SHA-256（内部 lockfile 构建期注入）
    private static final Map<String, String> LOCK = Map.of(
        "com.acme:core-utils:1.4.2",
        "9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08");
    // 缓存键包含全部影响头：repo+坐标+classifier，防止跨源缓存投毒
    private final Map<String, byte[]> cache = new ConcurrentHashMap<>();

    byte[] resolve(String gav, String classifier) throws Exception {
        if (!LOCK.containsKey(gav))
            throw new IllegalStateException("not pinned in lockfile: " + gav);
        for (String repo : PINNED_ORDER) {
            String key = repo + "|" + gav + "|" + classifier;
            byte[] jar = cache.get(key);
            if (jar == null) { jar = fetch(repo, gav, classifier); if (jar != null) cache.put(key, jar); }
            if (jar == null) continue;
            if (!sha256(jar).equals(LOCK.get(gav)))
                throw new SecurityException("digest mismatch: dependency confusion suspected");
            return jar;
        }
        throw new IllegalStateException("not found in pinned repos: " + gav);
    }
    private byte[] fetch(String repo, String gav, String cls) throws Exception {
        URI uri = URI.create(repo + "/" + gav.replace(':', '/') + "/" + cls + ".jar");
        try (InputStream in = uri.toURL().openStream()) {
            return in.readAllBytes();
        } catch (Exception e) { return null; }
    }
    private String sha256(byte[] data) throws Exception {
        StringBuilder sb = new StringBuilder();
        for (byte b : MessageDigest.getInstance("SHA-256").digest(data))
            sb.append(String.format("%02x", b));
        return sb.toString();
    }
}
